def full_text(item, lang):
    stem=item[0] if lang=='en' else item[1] if lang=='ur' else item[2]
    answer=item[3] if lang=='en' else item[4] if lang=='ur' else item[5]
    return stem+'\n(Answer: '+answer+')'

def circuit(lang):
    caption={'en':'Numerical question 11 — 3 μF in series with a parallel 2 μF and 5 μF branch; 6 V source','ur':'عددی سوال 11 — 3 مائیکروفیراڈ سلسلہ وار، 2 اور 5 مائیکروفیراڈ متوازی؛ 6 وولٹ منبع','ps':'11م عددي پوښتنه — 3 مایکروفارډ په لړۍ، 2 او 5 مایکروفارډ موازي؛ 6 ولټه سرچینه'}[lang]
    body='<path d="M55 70H125M153 70H235V115M235 205V250H55V70M350 115V205M350 160H405V250H252M235 115H282M296 115H350M235 205H282M296 205H350" fill="none" stroke="#334155" stroke-width="4"/><path d="M125 55V85M153 55V85M282 105V125M296 105V125M282 195V215M296 195V215" stroke="#0f172a" stroke-width="3"/><text x="108" y="45">3 μF</text><text x="274" y="96">2 μF</text><text x="274" y="238">5 μF</text><circle cx="240" cy="250" r="4" fill="#0f172a"/><circle cx="252" cy="250" r="4" fill="#0f172a"/><text x="205" y="280">+ 6 V −</text>'
    return '<figure>'+svg(body,440,300,'3 microfarad capacitor in series with parallel 2 and 5 microfarad capacitors; 6 volt battery')+'<figcaption>'+caption+'</figcaption></figure>'

def main():
    rows=[(full_text(item,'en'),full_text(item,'ur'),full_text(item,'ps')) for item in NUMERICAL]
    record={'id':'phys12-front-numerical50-51','title':'Exercise 11 — Numerical Questions (continued)','kind':'exercise','pdfPage':30,'printedPage':50,'sourcePdf':SOURCE,'paragraphs':[r[0] for r in rows]}
    layout=[{'type':'paragraph','indices':[i]} for i in range(10)]+[{'type':'paragraph','indices':[10]},{'type':'visual'}]
    item=section(record,rows,layout,('یونٹ 11 کی مشق — عددی سوالات (جاری)','د ۱۱م څپرکي تمرین — عددي پوښتنې (دوام)'))
    item.update(kind='exercise',diagramSvg=circuit('en'),diagramSvgUrdu=circuit('ur'),diagramSvgPashto=circuit('ps'),sourceReferences=[{'pdfPage':30,'printedPage':50,'sourcePdf':SOURCE},{'pdfPage':30,'printedPage':51,'sourcePdf':SOURCE}])
    item['content']+=item['diagramSvg']
    problems=[]
    for number,entry in enumerate(NUMERICAL,2):
        problem={'id':f'textbook-exercise-11-numerical-q{number}','qNo':str(number),'question':entry[0],'questionUrdu':entry[1],'questionPashto':entry[2],'answer':entry[3],'answerOrigin':'textbook','solutionOrigin':'textbook answer','sourceReferences':[{'pdfPage':30,'printedPage':50 if number<=8 else 51}]}
        if number==7: problem['sourceClarification']='The printed question asks for both distance and charge, but the printed answer supplies only the charge value; the incomplete answer is preserved.'
        if number==11:
            problem['diagramSvg']=circuit('en');problem['diagramSvgUrdu']=circuit('ur');problem['diagramSvgPashto']=circuit('ps')
            problem['sourceClarification']='The question asks for charge, but the printed answer is labeled μF, a capacitance unit. The source unit is preserved.'
        problems.append(problem)
    companions=json.loads((OUT/'physics-companions.json').read_text(encoding='utf-8'))
    numerical=next(x for x in companions['exercises'] if x['id']=='textbook-exercise-11-numerical')
    numerical['problems']=[p for p in numerical['problems'] if p['qNo']=='1']+problems
    sync_companions(exercises=[numerical])
    upsert([record],[item])
    progress=json.loads((OUT/'progress.json').read_text(encoding='utf-8'))
    if progress['nextPage']==30:
        checkpoint(30,'corrected_verified',[record['id']],
          'Original spread rendered at 2.5x and inspected. Numerical questions 2–12 transcribed with all textbook answers in printed order and paired translations. Question 11 capacitor network rebuilt as native SVG. The source’s incomplete answer to question 7 and charge/μF mismatch in question 11 are disclosed; no answers were invented.',printed_pages=[50,51])
    elif progress['lastFullyVerifiedPage']<30:
        raise RuntimeError('Unexpected checkpoint state; refusing to advance the review ledger')

if __name__=='__main__':
    main()
